/**
 * Invalid input or status transition
 */
export type BadRequestResponse = Error;

/**
 * Authentication required
 */
export type UnauthorizedResponse = Error;

/**
 * The staff role is not permitted
 */
export type ForbiddenResponse = Error;

/**
 * Patient, visit, supplier, or order not found
 */
export type NotFoundResponse = Error;

/**
 * Visit ownership conflict, inactive patient, or invalid lifecycle operation
 */
export type ConflictResponse = Error;

/**
 * Invalid input or mismatched patient relationship.
 */
export type AlignerBadRequestResponse = Error;

/**
 * Role or assigned-case ownership does not permit this action.
 */
export type AlignerForbiddenResponse = Error;

/**
 * Patient, course, case, visit, or tray was not found.
 */
export type AlignerNotFoundResponse = Error;

/**
 * Patient is inactive or sequence/course constraint conflicts.
 */
export type AlignerConflictResponse = Error;

/**
 * Request validation failed
 */
export type PrescriptionBadRequestResponse = PrescriptionError;

/**
 * Staff role is not permitted
 */
export type PrescriptionForbiddenResponse = PrescriptionError;

/**
 * Patient, visit, or prescription was not found
 */
export type PrescriptionNotFoundResponse = PrescriptionError;

/**
 * Invalid request.
 */
export type MarketingBadRequestResponse = MarketingError;

/**
 * Role is not authorized; only clinic owners and managers can use these endpoints.
 */
export type MarketingForbiddenResponse = MarketingError;

